<?php require __DIR__ . '/header.php'; $orders=(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(); $confirmed=(int)db()->query("SELECT COUNT(*) FROM orders WHERE status='Confirmed'")->fetchColumn(); $revenue=(float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status <> 'Cancelled'")->fetchColumn(); $max=max(1,$orders); ?><div class="dashboard-title"><div><p class="eyebrow"><?= $lang==='ar'?'الإحصائيات':'Statistics' ?></p><h2><?= $lang==='ar'?'أداء المتجر':'Store performance' ?></h2></div></div><section class="charts"><article class="chart-card"><div><span><?= text('orders') ?></span><strong><?= $orders ?></strong></div><div class="chart"><i style="height:<?= max(8, $orders / $max * 100) ?>%"></i><i style="height:<?= max(8, $confirmed / $max * 100) ?>%"></i><i style="height:<?= max(8, ($orders - $confirmed) / $max * 100) ?>%"></i></div><small><?= $lang==='ar'?'كل الطلبات / المؤكدة / الجديدة':'All / confirmed / new orders' ?></small></article><article class="chart-card"><div><span><?= $lang==='ar'?'الإيرادات':'Revenue' ?></span><strong><span class="money" dir="ltr"><?= number_format($revenue,0,',',' ') ?> DA</span></strong></div><div class="chart revenue"><i style="height:35%"></i><i style="height:55%"></i><i style="height:48%"></i><i style="height:75%"></i><i style="height:65%"></i><i style="height:90%"></i></div><small><?= $lang==='ar'?'ملخص الإيرادات':'Revenue overview' ?></small></article></section><?php require __DIR__ . '/footer.php'; ?>
